import{_ as e,C as n,c as i,o as t,j as r,b as s,a0 as a,a as l,w as h,G as d,a1 as o}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Wahrscheinlichkeitsbasierte Entscheidungsfindung","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/tactics/probability.md","filePath":"de/education/tactics/probability.md"}');const c=e({name:"de/education/tactics/probability.md"},[["render",function(e,u,c,g,b,k){const p=n("Mermaid");return t(),i("div",null,[u[1]||(u[1]=r("h1",{id:"wahrscheinlichkeitsbasierte-entscheidungsfindung",tabindex:"-1"},[l("Wahrscheinlichkeitsbasierte Entscheidungsfindung "),r("a",{class:"header-anchor",href:"#wahrscheinlichkeitsbasierte-entscheidungsfindung","aria-label":'Permalink to "Wahrscheinlichkeitsbasierte Entscheidungsfindung"'},"​")],-1)),u[2]||(u[2]=r("p",null,"Taktisches Denken auf höchstem Niveau nutzt Wahrscheinlichkeitsrechnung, um bessere Entscheidungen zu treffen. Anstatt zu raten oder sich auf sein Bauchgefühl zu verlassen, analysiert man systematisch seine Optionen.",-1)),u[3]||(u[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"Die große Idee"),r("p",null,[r("strong",null,"Denken Sie in Wahrscheinlichkeiten, nicht in Gewissheiten."),l(" Die beste Entscheidung ist nicht immer die aggressivste oder die sicherste – es ist diejenige, die Ihnen über viele ähnliche Situationen hinweg den besten erwarteten Nutzen bringt.")])],-1)),(t(),s(o,null,{default:h(()=>[d(p,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BEntscheidungspunkt%5D%20--%3E%20B%5BOption%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOption%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOption%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BErfolgswahrscheinlichkeit%5D%0A%20%20%20%20B%20--%3E%20F%5BBelohnung%20bei%20Erfolg%5D%0A%20%20%20%20B%20--%3E%20G%5BKosten%20im%20Falle%20eines%20Scheiterns%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BErfolgswahrscheinlichkeit%5D%0A%20%20%20%20C%20--%3E%20I%5BBelohnung%20bei%20Erfolg%5D%0A%20%20%20%20C%20--%3E%20J%5BKosten%20im%20Falle%20eines%20Scheiterns%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BErfolgswahrscheinlichkeit%5D%0A%20%20%20%20D%20--%3E%20L%5BBelohnung%20bei%20Erfolg%5D%0A%20%20%20%20D%20--%3E%20M%5BKosten%20im%20Falle%20eines%20Scheiterns%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BErwartungswert%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BErwartungswert%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BErwartungswert%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BW%C3%A4hlen%20Sie%20das%20beste%20Elektrofahrzeug%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...u[0]||(u[0]=[l(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=a('<h2 id="das-grundgerust" tabindex="-1">Das Grundgerüst <a class="header-anchor" href="#das-grundgerust" aria-label="Permalink to &quot;Das Grundgerüst&quot;">​</a></h2><p>Jeder Wurf besteht aus drei Komponenten:</p><table tabindex="0"><thead><tr><th>Komponente</th><th>Frage</th><th>Beispiel</th></tr></thead><tbody><tr><td><strong>Erfolgswahrscheinlichkeit</strong></td><td>Wie wahrscheinlich ist es, dass ich dies umsetze?</td><td>70 % Erfolgsquote bei dieser Entfernung</td></tr><tr><td><strong>Belohnung bei Erfolg</strong></td><td>Was habe ich davon?</td><td>Punktgewinn, Positionsgewinn</td></tr><tr><td><strong>Kosten bei Misserfolg</strong></td><td>Was verliere ich?</td><td>Dem Gegner einen leichten Punkt ermöglichen</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Die Formel</p><p><strong>Erwartungswert = (Wahrscheinlichkeit × Belohnung) - ((1 - Wahrscheinlichkeit) × Kosten)</strong></p><p>Gute Entscheidungen maximieren den erwarteten Wert im Laufe der Zeit.</p></div><h2 id="denken-in-wahrscheinlichkeiten" tabindex="-1">Denken in Wahrscheinlichkeiten <a class="header-anchor" href="#denken-in-wahrscheinlichkeiten" aria-label="Permalink to &quot;Denken in Wahrscheinlichkeiten&quot;">​</a></h2><p>Bei der Entscheidung zwischen den Optionen sollten Sie Folgendes berücksichtigen:</p><ul><li>Wie hoch ist meine realistische Erfolgsquote für jede Option?</li><li>Was habe ich davon, wenn es funktioniert?</li><li>Welche Kosten entstehen, wenn es fehlschlägt?</li><li>Wie beeinflusst die Spielsituation meine Entscheidung?</li></ul><p>Die beste Option ist nicht immer die aggressivste oder die sicherste – es ist diejenige, die in vielen ähnlichen Situationen das beste Ergebnis liefert.</p><h2 id="kenne-deine-zahlen" tabindex="-1">Kenne deine Zahlen <a class="header-anchor" href="#kenne-deine-zahlen" aria-label="Permalink to &quot;Kenne deine Zahlen&quot;">​</a></h2><p>Um Wahrscheinlichkeitsrechnung anwenden zu können, müssen Sie Ihre tatsächlichen Erfolgsquoten kennen:</p><table tabindex="0"><thead><tr><th>Wurfart</th><th>Distanz</th><th>Ihre Erfolgsquote</th></tr></thead><tbody><tr><td>Punkt (nahe)</td><td>6-7 m</td><td>___%</td></tr><tr><td>Punkt (mittel)</td><td>8-9 m</td><td>___%</td></tr><tr><td>Punkt (lang)</td><td>10 m+</td><td>___%</td></tr><tr><td>Schuss (aus nächster Nähe)</td><td>6-7 m</td><td>___%</td></tr><tr><td>Schießen (mittel)</td><td>8-9 m</td><td>___%</td></tr><tr><td>Schießen (lang)</td><td>10 m+</td><td>___%</td></tr></tbody></table><p>Verfolgen Sie diese Werte in der Praxis. Seien Sie ehrlich – die meisten Spieler überschätzen ihre Erfolgsquoten.</p><h2 id="anpassung-an-die-bedingungen" tabindex="-1">Anpassung an die Bedingungen <a class="header-anchor" href="#anpassung-an-die-bedingungen" aria-label="Permalink to &quot;Anpassung an die Bedingungen&quot;">​</a></h2><p>Ihre Grundgebühren ändern sich je nach:</p><table tabindex="0"><thead><tr><th>Faktor</th><th>Auswirkung auf die Erfolgsquote</th></tr></thead><tbody><tr><td>Unbekanntes Terrain</td><td>-10 bis -20 %</td></tr><tr><td>Drucksituation</td><td>-5 bis -15 %</td></tr><tr><td>Ermüdung</td><td>-5 bis -10%</td></tr><tr><td>Selbstvertrauen (hoch)</td><td>+5 bis +10%</td></tr><tr><td>Jüngste Erfolge</td><td>+5 %</td></tr><tr><td>Jüngstes Versagen</td><td>-5 bis -10%</td></tr></tbody></table><p>Seien Sie bei diesen Anpassungen realistisch.</p><h2 id="das-boule-vorteilsprinzip" tabindex="-1">Das Boule-Vorteilsprinzip <a class="header-anchor" href="#das-boule-vorteilsprinzip" aria-label="Permalink to &quot;Das Boule-Vorteilsprinzip&quot;">​</a></h2><p>Wenn du mehr Kugeln übrig hast als dein Gegner:</p><p><strong>Priorität 1: Den Punkt sichern</strong></p><ul><li>Stellen Sie zunächst sicher, dass Sie mindestens einen Punkt halten.</li><li>Werde nicht gierig, bevor du die Grundlagen gesichert hast.</li></ul><p><strong>Priorität 2: Maximale Punktzahl bei kalkuliertem Risiko</strong></p><ul><li>Sobald Sie die Position halten, prüfen Sie, ob Sie weitere Punkte hinzufügen können.</li><li>Jeder weitere Wurf ist eine Risiko-Nutzen-Abwägung.</li><li>Verwandle einen sicheren 2-Punkte-Sieg nicht durch Übermut in eine Niederlage.</li></ul><p><strong>Weniger Boules übrig:</strong> Jeder Wurf muss sitzen. Sichere Spielzüge reichen möglicherweise nicht aus – überlegen Sie sich risikoreichere Optionen, um am Ende wieder aufzuholen.</p><h2 id="das-„une-boule-devant-prinzip" tabindex="-1">Das „Une Boule Devant“-Prinzip <a class="header-anchor" href="#das-„une-boule-devant-prinzip" aria-label="Permalink to &quot;Das „Une Boule Devant“-Prinzip&quot;">​</a></h2><p>Eine Boule-Kugel vor dem Buben (zwischen Bube und Gegner) ist äußerst wertvoll:</p><ul><li>Es blockiert direkte Linien</li><li>Es zwingt die Gegner, einen Umweg zu machen oder ihn zu überqueren.</li><li>Es kann ankommende Kugeln ablenken</li><li>Es ist eine „Geldkugel“ – es lohnt sich, sie zu schützen.</li></ul><p><strong>Taktische Implikation:</strong> Manchmal ist es besser, eine blockierende Boule zu platzieren, als zu versuchen, so nah wie möglich heranzukommen.</p><h2 id="risikotoleranz-nach-spielstaat" tabindex="-1">Risikotoleranz nach Spielstaat <a class="header-anchor" href="#risikotoleranz-nach-spielstaat" aria-label="Permalink to &quot;Risikotoleranz nach Spielstaat&quot;">​</a></h2><h3 id="mit-zeitlimit" tabindex="-1">Mit Zeitlimit <a class="header-anchor" href="#mit-zeitlimit" aria-label="Permalink to &quot;Mit Zeitlimit&quot;">​</a></h3><p>Bei Spielen mit Zeitlimit ist die Punktedifferenz entscheidend:</p><table tabindex="0"><thead><tr><th>Spielstand</th><th>Risikoansatz</th></tr></thead><tbody><tr><td>mit 4+ Punkten Vorsprung</td><td>Sehr konservativ – Blei schützen, Zeit stoppen</td></tr><tr><td>Führung mit 1:3</td><td>Konservativ – keine Punkte verschenken</td></tr><tr><td>Gebunden</td><td>Ausgewogene – kalkulierte Risiken</td></tr><tr><td>Rückstand 1-3</td><td>Aggressiv – Bedürfnis, Boden gutzumachen</td></tr><tr><td>Rückstand 4+</td><td>Sehr aggressiv – wir müssen Risiken eingehen, die Zeit drängt.</td></tr></tbody></table><h3 id="ohne-zeitbegrenzung" tabindex="-1">Ohne Zeitbegrenzung <a class="header-anchor" href="#ohne-zeitbegrenzung" aria-label="Permalink to &quot;Ohne Zeitbegrenzung&quot;">​</a></h3><p>Wenn kein Zeitdruck besteht:</p><ul><li>Halte dich an deinen Spielplan – ändere deine Strategie nicht nur wegen des Spielstands.</li><li>Das Ergebnis wird schwanken – vertraue deiner Herangehensweise.</li><li>Überlegen Sie sich nur dann eine Änderung Ihrer Strategie, wenn diese gegen diesen Gegner eindeutig nicht funktioniert.</li><li>Panikreaktionen, wenn man in Rückstand gerät, verschlimmern die Situation oft nur.</li></ul><h3 id="anpassungen-im-endspiel" tabindex="-1">Anpassungen im Endspiel <a class="header-anchor" href="#anpassungen-im-endspiel" aria-label="Permalink to &quot;Anpassungen im Endspiel&quot;">​</a></h3><p><strong>Wenn man dieses Ende gewinnt, gewinnt man das Spiel:</strong></p><ul><li>Sei konservativer.</li><li>Riskieren Sie nicht, mehrere Punkte zu verlieren.</li><li>Ein einzelner Punkt könnte genügen.</li></ul><p><strong>Verliert man dieses Ende, verliert man das Spiel:</strong></p><ul><li>Größere Risiken eingehen</li><li>Es müssen mehrere Punkte erzielt werden.</li><li>Vorsichtiges Spielen wird dich nicht retten</li></ul><h2 id="haufige-fehler-bei-wahrscheinlichkeitsrechnungen" tabindex="-1">Häufige Fehler bei Wahrscheinlichkeitsrechnungen <a class="header-anchor" href="#haufige-fehler-bei-wahrscheinlichkeitsrechnungen" aria-label="Permalink to &quot;Häufige Fehler bei Wahrscheinlichkeitsrechnungen&quot;">​</a></h2><h3 id="_1-selbstuberschatzung" tabindex="-1">1. Selbstüberschätzung <a class="header-anchor" href="#_1-selbstuberschatzung" aria-label="Permalink to &quot;1. Selbstüberschätzung&quot;">​</a></h3><p>„Den Wurf kann ich treffen“ – aber schaffst du es auch 7 von 10 Mal? Sei ehrlich.</p><h3 id="_2-ignorieren-der-basiszinssatze" tabindex="-1">2. Ignorieren der Basiszinssätze <a class="header-anchor" href="#_2-ignorieren-der-basiszinssatze" aria-label="Permalink to &quot;2. Ignorieren der Basiszinssätze&quot;">​</a></h3><p>Deine Trefferquote ändert sich nicht, nur weil der Moment wichtig ist.</p><h3 id="_3-sunk-cost-fallacy-versunkene-kosten-trugschluss" tabindex="-1">3. Sunk-Cost-Fallacy (Versunkene-Kosten-Trugschluss) <a class="header-anchor" href="#_3-sunk-cost-fallacy-versunkene-kosten-trugschluss" aria-label="Permalink to &quot;3. Sunk-Cost-Fallacy (Versunkene-Kosten-Trugschluss)&quot;">​</a></h3><p>„Ich habe schon zweimal daneben geworfen, ich sollte weiterwerfen“ – jeder Wurf ist unabhängig.</p><h3 id="_4-ergebnisverzerrung" tabindex="-1">4. Ergebnisverzerrung <a class="header-anchor" href="#_4-ergebnisverzerrung" aria-label="Permalink to &quot;4. Ergebnisverzerrung&quot;">​</a></h3><p>Ein riskanter Schuss, der gelang, war dennoch riskant. Ein sicherer Spielzug, der scheiterte, war dennoch richtig.</p><h3 id="_5-die-optionen-des-gegners-ignorieren" tabindex="-1">5. Die Optionen des Gegners ignorieren <a class="header-anchor" href="#_5-die-optionen-des-gegners-ignorieren" aria-label="Permalink to &quot;5. Die Optionen des Gegners ignorieren&quot;">​</a></h3><p>Überlege, was sie nach deinem Wurf tun werden, egal ob er gelingt oder nicht.</p><h2 id="praktische-anwendung" tabindex="-1">Praktische Anwendung <a class="header-anchor" href="#praktische-anwendung" aria-label="Permalink to &quot;Praktische Anwendung&quot;">​</a></h2><h3 id="vor-jedem-wurf" tabindex="-1">Vor jedem Wurf <a class="header-anchor" href="#vor-jedem-wurf" aria-label="Permalink to &quot;Vor jedem Wurf&quot;">​</a></h3><ol><li><strong>Optionen identifizieren</strong> (zielen, schießen, blocken usw.).</li><li>Schätzen Sie die Erfolgswahrscheinlichkeit für jedes Element ein.</li><li><strong>Berücksichtigen Sie die möglichen Folgen</strong> (Erfolg und Misserfolg)</li><li><strong>Spielstand berücksichtigen</strong> (Punktzahl, verbleibende Boules)</li><li><strong>Wählen Sie</strong> die Option mit dem besten erwarteten Wert</li><li><strong>Volle Hingabe</strong> – kein Zögern während der Ausführung</li></ol><h3 id="intuition-entwickeln" tabindex="-1">Intuition entwickeln <a class="header-anchor" href="#intuition-entwickeln" aria-label="Permalink to &quot;Intuition entwickeln&quot;">​</a></h3><p>Mit der Zeit wird das Denken in Wahrscheinlichkeiten intuitiv:</p><ul><li>Verfolgen Sie Ihre Ergebnisse ehrlich.</li><li>Entscheidungen nach den Spielen überprüfen</li><li>Erkennen Sie Muster in Ihren Erfolgsquoten</li><li>Passen Sie Ihr mentales Modell an</li></ul><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Gute Entscheidungen führen nicht immer zu guten Ergebnissen. Aber gute Entscheidungen führen im Laufe der Zeit zu besseren Resultaten.</p></blockquote><p>Denken Sie in Wahrscheinlichkeiten. Kennen Sie Ihre Zahlen. Treffen Sie die kluge Entscheidung, nicht die auf gut Glück basierende.</p>',59))])}]]);export{u as __pageData,c as default};
